package app.noir.mobile;

import android.app.*;
import android.net.Uri;
import android.view.*;
import android.widget.*;
import org.json.*;
import org.videolan.libvlc.MediaPlayer;
import org.videolan.libvlc.interfaces.IMedia;
import java.util.*;
import java.util.concurrent.*;

/** Player subtitle controls and background work; native calls stay on the UI thread. */
final class PlayerSubtitles {
    static{StreamSubtitleSync.init();}
    final PlayerActivity host;final DataStore data;final SubtitleClient client;final String id;
    final ExecutorService work=Executors.newSingleThreadExecutor();final Set<String> attached=new HashSet<>();
    StreamSubtitleSync streamSync;volatile boolean syncing=false;boolean chosenTrack=false,manual=false,playing=false,busy=false,closed=false,autoAttempted=false;String trackSignature="",notice="";JSONObject selectedFile;
    AlertDialog dialog;LinearLayout body;TextView status;boolean replaceSaved=false;
    PlayerSubtitles(PlayerActivity host){this.host=host;data=host.data;id=host.item.optString("id");client=new SubtitleClient(data,host.item);if(host.getIntent().getStringExtra("streamUrl")!=null&&data.localFile(id).isEmpty())client.streaming(host.getIntent().getStringExtra("streamRelease"));}
    void start(){attachSaved(false);work.execute(()->{String release="";if(client.streamRelease==null){try{JSONObject response=data.pcRequest("/v1/subtitle-tools/"+id,null);data.subtitleFiles(id,response.getJSONArray("files"));if(!response.optString("hash").isEmpty())release=response.optString("hash")+":"+response.optString("release");}catch(Exception ignored){}String identity=release;host.runOnUiThread(()->{if(!closed)host.usePcRelease(identity);});JSONObject latest=data.item(id);try{if(latest!=null)data.cacheSubtitles(latest);}catch(Exception ignored){}}host.runOnUiThread(()->{if(!closed){attachSaved(false);refresh();}});});}

    void playing(){playing=true;host.player.setSpuDelay((long)(data.subtitleDelay(id)*1_000_000));attachSaved(false);poll();if(client.streamRelease!=null&&!autoAttempted){autoAttempted=true;host.handler.postDelayed(this::autoStreamSubtitle,2500);}}
    void autoStreamSubtitle(){
        if(closed||manual||busy||host.player==null)return;String language=data.subtitleLanguage(id),lang=SubtitleClient.language(language);if(lang.isEmpty())return;
        MediaPlayer.TrackDescription[] tracks=host.player.getSpuTracks();if(tracks!=null)for(MediaPlayer.TrackDescription track:tracks)if(track.id>=0&&PlayerActivity.subtitleScore(track.name,language)>=0)return;
        busy=true;notice=host.tv?PlayerPrefs.f("Finding %s subtitles…",t(language)):"Finding "+language+" subtitles…";refresh();
        work.execute(()->{try{
            List<JSONObject> found=client.search(lang);JSONObject sub=found.isEmpty()?null:client.download(found.get(0));
            host.runOnUiThread(()->{if(closed)return;busy=false;if(!manual&&data.subtitleLanguage(id).equals(language)&&sub!=null)selectFile(sub);notice=sub==null?(host.tv?PlayerPrefs.f("No %s subtitle found. Try Download subtitles.",t(language)):"No "+language+" subtitle found. Try Download subtitles."):t("Subtitle saved · use Adjust timing if needed");refresh();});
        }catch(Exception e){host.runOnUiThread(()->{if(closed)return;busy=false;notice="Subtitles unavailable · retry Download subtitles";refresh();});}});
    }
    void poll(){if(closed||!playing||host.player==null||manual)return;MediaPlayer.TrackDescription[] tracks=host.player.getSpuTracks();if(tracks==null)return;StringBuilder signature=new StringBuilder();for(MediaPlayer.TrackDescription t:tracks)signature.append(t.id).append(':').append(t.name).append('|');String current=signature.toString();if(current.equals(trackSignature))return;trackSignature=current;
        int exact=PlayerPrefs.preferredTrack(tracks,data.trackPreference(id,host.trackRelease(),"subtitle"));if(exact>=0){host.player.setSpuTrack(exact);refresh();return;}String language=data.subtitleLanguage(id);if(language.equals("Off")){host.player.setSpuTrack(-1);return;}int chosen=-1,best=-1,usable=0,only=-1;for(MediaPlayer.TrackDescription t:tracks)if(t.id>=0){usable++;only=t.id;int score=PlayerActivity.subtitleScore(t.name,language);if(score>best){best=score;chosen=t.id;}}
        // An unlabelled single track is usable; unknown multi-language tracks need an explicit choice.
        if(chosen<0&&usable==1&&PlayerActivity.subtitleScore(tracks[tracks.length-1].name,language.equals("Arabic")?"English":"Arabic")<0)chosen=only;
        if(chosen>=0)host.player.setSpuTrack(chosen);refresh();
    }
    void attachSaved(boolean force){if(closed||host.player==null||!playing)return;String language=data.subtitleLanguage(id);boolean selected=false;List<JSONObject> saved=client.files();String preferred=data.preferredSubtitle(id);saved.sort(Comparator.comparingInt(s->s.optString("id").equals(preferred)?0:1));for(JSONObject sub:saved){
        if(attached.contains(sub.optString("id")))continue;boolean use=!manual&&!selected&&data.trackPreference(id,host.trackRelease(),"subtitle").length()==0&&!preferred.equals("embedded")&&!language.equals("Off")&&(PlayerActivity.subtitleScore(sub.optString("name"),language)>=0||sub.optString("name").equals("External subtitles"));
        if(host.player.addSlave(IMedia.Slave.Type.Subtitle,Uri.fromFile(data.subtitle(sub)),use)){attached.add(sub.optString("id"));if(use){selected=true;selectedFile=sub;manual=true;}}}
        if(force&&selectedFile!=null)selectFile(selectedFile);}
    void selectFile(JSONObject sub){if(closed||host.player==null)return;chosenTrack=true;manual=true;String lang=sub.optString("language");if(lang.isEmpty())lang=PlayerActivity.subtitleScore(sub.optString("name"),"Arabic")>=0?"ar":"en";data.subtitlePreference(id,SubtitleClient.label(lang),data.subtitleDelay(id));if(host.player.addSlave(IMedia.Slave.Type.Subtitle,Uri.fromFile(data.subtitle(sub)),true)){selectedFile=sub;data.trackPreference(id,host.trackRelease(),"subtitle","","");data.subtitleFilePreference(id,sub.optString("id"));attached.add(sub.optString("id"));host.player.setSpuDelay((long)(data.subtitleDelay(id)*1_000_000));feedback(host.tv?PlayerPrefs.f("Using %s",sub.optString("name")):"Using "+sub.optString("name"));}else feedback("The subtitle is saved. Retry selecting it after playback starts.");refresh();}
    String t(String text){return host.playerText(text);}
    void show(){host.handler.removeCallbacks(host.hide);LinearLayout panel=new LinearLayout(host);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(host.dp(18),host.dp(8),host.dp(18),host.dp(12));ScrollView scroll=new ScrollView(host);scroll.addView(panel);body=panel;dialog=new AlertDialog.Builder(host).setTitle(t("Subtitles")).setView(scroll).setNegativeButton(t("Close"),(d,w)->host.show()).create();if(host.tv)host.tvDialog(dialog,()->{dialog=null;host.show();});else dialog.setOnDismissListener(d->{dialog=null;host.show();});dialog.show();refresh();}
    void refresh(){if(dialog==null||!dialog.isShowing()||body==null||closed)return;View focused=host.tv?dialog.getCurrentFocus():null;String focusLabel=focused instanceof TextView?((TextView)focused).getText().toString():"";body.removeAllViews();status=host.text(busy?t("Working in the background…"):!notice.isEmpty()?t(notice):host.tv?PlayerPrefs.f("%s · timing %+.2fs",t(data.subtitleLanguage(id)),data.subtitleDelay(id)):data.subtitleLanguage(id)+" · timing "+String.format(Locale.ROOT,"%+.2fs",data.subtitleDelay(id)),13);status.setPadding(0,host.dp(8),0,host.dp(12));body.addView(status);
        MediaPlayer.TrackDescription[] tracks=host.player.getSpuTracks();RadioGroup group=new RadioGroup(host);body.addView(group);RadioButton off=radio(t("Off"));group.addView(off);Map<Integer,MediaPlayer.TrackDescription> ids=new HashMap<>();if(host.player.getSpuTrack()<0)group.check(off.getId());
        if(tracks!=null)for(MediaPlayer.TrackDescription track:tracks)if(track.id>=0){RadioButton choice=radio(track.name);group.addView(choice);ids.put(choice.getId(),track);if(track.id==host.player.getSpuTrack())group.check(choice.getId());}
        group.setOnCheckedChangeListener((g,checked)->{chosenTrack=true;manual=true;selectedFile=null;data.subtitleFilePreference(id,"embedded");if(checked==off.getId()){data.trackPreference(id,host.trackRelease(),"subtitle","","");host.player.setSpuTrack(-1);data.subtitlePreference(id,"Off",data.subtitleDelay(id));}else{MediaPlayer.TrackDescription track=ids.get(checked);if(track!=null){host.player.setSpuTrack(track.id);data.trackPreference(id,host.trackRelease(),"subtitle",PlayerPrefs.trackKey(track.name,track.id),PlayerPrefs.trackLanguage(track.name));String language=PlayerActivity.subtitleScore(track.name,"Arabic")>=0?"Arabic":PlayerActivity.subtitleScore(track.name,"English")>=0?"English":data.subtitleLanguage(id).equals("Off")?"English":data.subtitleLanguage(id);data.subtitlePreference(id,language,data.subtitleDelay(id));}}});
        List<JSONObject> saved=client.files();if(!saved.isEmpty()){body.addView(host.text("Saved for offline use",15));for(JSONObject sub:saved)body.addView(action(sub.optString("name")+(sub.optBoolean("aligned")?" · "+t("synced"):""),()->selectFile(sub)));}
        body.addView(action("Download English subtitles",()->search("en")));body.addView(action("Download Arabic subtitles",()->search("ar")));{CheckBox replace=new CheckBox(host);replace.setText(t("Replace saved subtitles"));replace.setTextColor(MainActivity.WHITE);replace.setChecked(replaceSaved);replace.setEnabled(!busy);replace.setOnCheckedChangeListener((b,on)->replaceSaved=on);body.addView(replace);}
        body.addView(action("Smart sync saved subtitles",client.streamRelease==null?this::syncMenu:this::streamSyncMenu));if(streamSync!=null&&syncing){Button cancel=host.button(t("Cancel timing check"),streamSync::cancel);cancel.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));body.addView(cancel);}body.addView(action("Adjust timing",this::timing));
        TextView note=host.text(t(client.streamRelease!=null?"Download subtitles while streaming, without your PC. Saved subtitles reload for this release. Smart sync listens to short parts of the stream and keeps the original if it isn't sure.":"Downloads match this movie or episode. Smart sync checks timing on your paired PC and keeps the original when uncertain. Saved subtitles and timing controls work offline."),12);note.setPadding(0,host.dp(12),0,0);body.addView(note);if(host.tv){ArrayList<View> matches=new ArrayList<>();if(!focusLabel.isEmpty())body.findViewsWithText(matches,focusLabel,View.FIND_VIEWS_WITH_TEXT);View target=matches.isEmpty()?group.findViewById(group.getCheckedRadioButtonId()):matches.get(0);if(target==null)target=off;target.requestFocus();}
    }
    RadioButton radio(String label){RadioButton b=new RadioButton(host);b.setId(View.generateViewId());b.setText(t(label));if(host.tv){b.setTextSize(16);b.setMinHeight(host.dp(48));}b.setTextColor(MainActivity.WHITE);return b;}
    Button action(String label,Runnable task){Button b=host.button(t(label),task);b.setLayoutParams(new LinearLayout.LayoutParams(-1,-2));b.setEnabled(!busy);return b;}
    interface Task{void run()throws Exception;}
    void run(String message,Task task){if(busy||closed)return;busy=true;refresh();feedback(message);work.execute(()->{try{task.run();}catch(Exception e){host.runOnUiThread(()->feedback(e.getMessage()==null?"Couldn't finish subtitle request. Try again.":e.getMessage()));}finally{host.runOnUiThread(()->{busy=false;if(!closed)refresh();});}});}
    void feedback(String text){if(closed)return;text=t(text);notice=text;if(status!=null&&dialog!=null&&dialog.isShowing())status.setText(text);else Toast.makeText(host,text,Toast.LENGTH_LONG).show();}
    void search(String lang){run(host.tv?PlayerPrefs.f("Finding %s subtitles…",t(SubtitleClient.label(lang))):"Finding "+SubtitleClient.label(lang)+" subtitles…",()->{List<JSONObject> found=client.search(lang);lastFound=found;host.runOnUiThread(()->{if(closed)return;busy=false;if(found.isEmpty()){feedback(host.tv?PlayerPrefs.f("No %s subtitle found. Try again later.",t(SubtitleClient.label(lang))):"No "+SubtitleClient.label(lang)+" subtitle found. Try again later.");return;}List<JSONObject> choices=found.subList(0,Math.min(12,found.size()));String[] labels=new String[choices.size()];for(int n=0;n<choices.size();n++){JSONObject c=choices.get(n);String release=c.optString("movieReleaseName");if(release.isEmpty())release=c.optString("subtitleFileName",t("Available release"));labels[n]=(c.optString("m").equals("h")?t("Exact video match")+" · ":n==0?t("Best available match")+" · ":"")+release;}host.tvDialog(new AlertDialog.Builder(host).setTitle(t(SubtitleClient.label(lang)+" subtitles")).setItems(labels,(d,n)->download(choices.get(n))).setNegativeButton(t("Cancel"),null).create(),()->refresh()).show();});});}
    List<JSONObject> lastFound=new ArrayList<>();
    void download(JSONObject choice){run("Downloading subtitles…",()->{client.replace=replaceSaved;SubtitleClient.Checked checked=client.downloadAndCheck(choice,lastFound,downloaded->host.runOnUiThread(()->{if(!closed){selectFile(downloaded);feedback("Subtitle saved. Checking timing…");}}));
        final JSONObject ready=checked.sub;final String text=SubtitleClient.resultLine(ready,checked.tail);host.runOnUiThread(()->{if(!closed){if(ready.optBoolean("aligned"))data.subtitlePreference(id,data.subtitleLanguage(id),0);selectFile(ready);feedback(text);}});});}
    void syncMenu(){List<JSONObject> files=client.files();if(files.isEmpty()){feedback("Download or save a subtitle first. Embedded tracks already use the release's timing.");return;}String[] labels=new String[files.size()];for(int n=0;n<files.size();n++)labels[n]=files.get(n).optString("name");host.tvDialog(new AlertDialog.Builder(host).setTitle(t("Choose subtitle to sync")).setItems(labels,(d,n)->run("Checking subtitle timing on PC…",()->{JSONObject synced=client.sync(files.get(n));host.runOnUiThread(()->{if(!closed){data.subtitlePreference(id,data.subtitleLanguage(id),0);selectFile(synced);feedback("Timing checked · original backed up on phone");}});})).setNegativeButton(t("Cancel"),null).create(),()->refresh()).show();}
    void streamSyncMenu(){List<JSONObject> files=client.files();if(files.isEmpty()){feedback("Download or save a subtitle first. Embedded tracks already use the release's timing.");return;}String[] labels=new String[files.size()];for(int n=0;n<files.size();n++)labels[n]=files.get(n).optString("name");host.tvDialog(new AlertDialog.Builder(host).setTitle(t("Choose subtitle to sync")).setItems(labels,(d,n)->askData(()->startStreamSync(files.get(n)))).setNegativeButton(t("Cancel"),null).create(),()->refresh()).show();}
    void askData(Runnable go){if(!StreamSubtitleSync.metered(host)){go.run();return;}host.tvDialog(new AlertDialog.Builder(host).setTitle(t("Timing check uses mobile data")).setMessage(t("This listens to about a tenth of the stream's audio over your mobile data. Continue?")).setPositiveButton(t("Continue"),(d,w)->go.run()).setNegativeButton(t("Cancel"),null).create(),()->refresh()).show();}
    void startStreamSync(JSONObject sub){if(streamSync==null||streamSync.isCancelled()||streamSync.duration<=0){String url=host.getIntent().getStringExtra("streamUrl");if(url==null)return;int audio=-1;MediaPlayer.TrackDescription[] tracks=host.player==null?null:host.player.getAudioTracks();if(tracks!=null&&host.player!=null){int position=0;for(MediaPlayer.TrackDescription track:tracks)if(track.id>=0){if(track.id==host.player.getAudioTrack()){audio=position;break;}position++;}}streamSync=new StreamSubtitleSync(host,url,host.getIntent().getStringExtra("streamAgent"),host.getIntent().getStringExtra("streamReferrer"),host.duration,audio);}StreamSubtitleSync job=streamSync;syncing=true;run("Listening to short parts of the stream…",()->{try{JSONObject synced=job.sync(sub,client,data,text->host.runOnUiThread(()->{if(!closed)feedback(text);}));double offset=synced.optDouble("timingOffset");host.runOnUiThread(()->{if(closed)return;data.subtitlePreference(id,data.subtitleLanguage(id),0);selectFile(synced);feedback(String.format(Locale.ROOT,t("Timing corrected · %+.2fs · original kept"),offset));});}finally{syncing=false;}});}
    void timing(){LinearLayout panel=new LinearLayout(host);panel.setOrientation(LinearLayout.VERTICAL);panel.setPadding(host.dp(20),host.dp(12),host.dp(20),host.dp(12));TextView value=host.text("",18);panel.addView(value);Runnable update=()->value.setText(String.format(Locale.ROOT,t("Subtitle timing: %+.2fs"),data.subtitleDelay(id)));update.run();panel.addView(host.text("If text appears late, choose Earlier. If text appears too soon, choose Later.",13));for(String label:new String[]{"Earlier · −0.5s","Later · +0.5s","Reset timing"})panel.addView(host.button(label,()->{double delay=label.startsWith("Reset")?0:data.subtitleDelay(id)+(label.startsWith("Earlier")?-.5:.5);data.subtitlePreference(id,data.subtitleLanguage(id),delay);host.player.setSpuDelay((long)(data.subtitleDelay(id)*1_000_000));update.run();}));host.tvDialog(new AlertDialog.Builder(host).setTitle(t("Subtitle timing")).setView(panel).setPositiveButton(t("Done"),(d,w)->refresh()).create(),()->refresh()).show();}
    void close(){closed=true;if(streamSync!=null)streamSync.cancel();work.shutdownNow();if(dialog!=null)dialog.dismiss();}
}
